{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.store_replen_5_May2025 as WITH SKU_SUMMARY AS ( SELECT SKU_CODE, SUM(TOTAL_REPLEN_REQ) AS CUML_REPLEN_REQ, SUM(ALLOCATED_UNITS) AS CUML_ALLO FROM snitch_db.maplemonk.store_replen_4_May2025 GROUP BY SKU_CODE ), INTERIM_ALLO AS ( SELECT t.SKU_CODE, t.BRANCH_CODE, t.FINAL_ACTION, t.PARETO, t.PRIORITY, t.FACILITY, t.REPLEN_ORDER, t.TOTAL_REPLEN_REQ, t.ALLOCATED_UNITS, s.CUML_REPLEN_REQ, s.CUML_ALLO, CASE WHEN s.CUML_ALLO >= s.CUML_REPLEN_REQ THEN t.ALLOCATED_UNITS ELSE CEIL(s.CUML_ALLO * t.TOTAL_REPLEN_REQ / s.CUML_REPLEN_REQ) END AS INTERIM_ALLO FROM snitch_db.maplemonk.store_replen_4_May2025 t INNER JOIN SKU_SUMMARY s ON t.SKU_CODE = s.SKU_CODE ), SOCIALISTIC_ALLO AS ( SELECT i.*, CASE WHEN SUM(INTERIM_ALLO) OVER (PARTITION BY SKU_CODE ORDER BY REPLEN_ORDER ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) <= CUML_ALLO THEN INTERIM_ALLO ELSE 0 END AS SOCIALISTIC FROM INTERIM_ALLO i ) SELECT * FROM SOCIALISTIC_ALLO; create or replace table snitch_db.maplemonk.store_replen_6_May2025 as with Agg_JIT AS ( SELECT \"ITEM CODE\" AS SKU_CODE, BRANCH_CODE, SUM(QTY) AS total_jit_qty FROM SNITCH_DB.MAPLEMONK.JIT_OFFLINE_GOODS GROUP BY \"ITEM CODE\", BRANCH_CODE ), Agg_L AS ( SELECT ADDLITEMCODE AS SKU_CODE, BRANCH_CODE, SUM(STOCK_QTY) AS total_stock_qty FROM SNITCH_DB.MAPLEMONK.LOGICERP23_24_GET_STOCK_IN_HAND WHERE DATE = CURRENT_DATE GROUP BY ADDLITEMCODE, BRANCH_CODE ) SELECT S5.* FROM SNITCH_DB.MAPLEMONK.store_replen_5_May2025 S5 JOIN SNITCH_DB.MAPLEMONK.store_replen_2_May2025 S2 ON S5.SKU_CODE = S2.logicusercode AND S5.BRANCH_CODE = S2.BRANCH_CODE LEFT JOIN Agg_L L ON S5.SKU_CODE = L.SKU_CODE AND S5.BRANCH_CODE = L.BRANCH_CODE LEFT JOIN Agg_JIT J ON S5.SKU_CODE = J.SKU_CODE AND S5.BRANCH_CODE = J.BRANCH_CODE WHERE NOT (S2.FINAL_ROS < 0.6 AND (S5.SOCIALISTIC + COALESCE(L.total_stock_qty, 0) + COALESCE(J.total_jit_qty, 0)) > 6); create or replace table snitch_db.maplemonk.replen_uc_import_master as WITH replen_output AS ( SELECT branch_code, sku_code, facility, socialistic FROM snitch_db.maplemonk.store_replen_6_may2025 WHERE socialistic > 0 AND branch_code != 98 QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_code, branch_code, facility ORDER BY socialistic DESC ) = 1 ), MAX_ORDER_NUM AS ( SELECT MAX(RIGHT(order_name, 4)) AS order_name_max FROM ( SELECT *, TO_DATE(\"DATE\", \'DD/MM/YYYY\') AS converted_date FROM snitch_db.maplemonk.GS_B2B_UC WHERE TO_DATE(\"DATE\", \'DD/MM/YYYY\') >= \'2025-09-01\' ) ), STORE_DETAILS_UC AS ( SELECT * FROM SNITCH_DB.MAPLEMONK.GS__SO_IMPORT_MASTER WHERE so_code NOT LIKE \'%QC-%\' ), COST_PRICE_MAPPING AS ( SELECT SKU, MAX(COST_PRICE) AS cost_price FROM SNITCH_DB.MAPLEMONK.UC_FINAL_ITEM_MASTER GROUP BY 1 ), SO_number_prep AS ( SELECT r.*, LPAD( TO_VARCHAR( COALESCE(m.order_name_max, 0) + CASE r.facility WHEN \'SAPL-WH2\' THEN 1 WHEN \'SAPL-WH1\' THEN 2 WHEN \'SAPL_EMIZA\' THEN 3 ELSE 0 END ), 4, \'0\' ) AS so_number_4d FROM replen_output r CROSS JOIN MAX_ORDER_NUM m ), store_details_join AS ( SELECT p.*, uc.so_code, CONCAT(COALESCE(uc.so_code, \'\'), COALESCE(p.so_number_4d, \'\')) AS so_code_so_number, CASE WHEN UPPER(TRIM(uc.state)) IN (\'GUJARAT\',\'MADHYA PRADESH\',\'RAJASTHAN\',\'UTTAR PRADESH\') THEN cosp.cost_price * 1.25 ELSE cosp.cost_price END AS cost_price FROM SO_number_prep p LEFT JOIN STORE_DETAILS_UC uc ON p.branch_code = uc.store_code LEFT JOIN COST_PRICE_MAPPING cosp ON p.sku_code = cosp.sku ), store_details_join_seq AS ( SELECT sdj.*, ROW_NUMBER() OVER ( PARTITION BY sdj.so_code_so_number ORDER BY sdj.sku_code, sdj.branch_code, sdj.facility ) AS item_seq FROM store_details_join sdj ), FINAL_OUTPUT AS ( SELECT sdj.so_code_so_number AS \"Sales Order Code*\", sdj.so_code_so_number AS \"Display Sales Order Code\", uc.EMAIL_ID AS \"Notification Email\", NULL AS \"Notification Mobile\", 1 AS \"COD*\", uc.CHANNEL AS \"Channel\", NULL AS \"Priority\", uc.STORE_CODE AS \"Shipping Address Id\", uc.SHIPPING_ADDRESS_NAME AS \"Shipping Address Name\", uc.SHIPPING_ADDRESS_LINE_2 AS \"Shipping Address Line 1\", uc.COMPANY_NAME AS \"Shipping Address Line 2\", uc.SHIPPING_ADDRESS_CITY AS \"Shipping Address City\", uc.SHIPPING_ADDRESS_STATE AS \"Shipping Address State\", uc.SHIPPING_ADDRESS_COUNTRY AS \"Shipping Address Country\", uc.SHIPPING_ADDRESS_PINCODE AS \"Shipping Address Pincode\", NULL AS \"Shipping Address Latitude\", NULL AS \"Shipping Address Longitude\", uc.SHIPPING_ADDRESS_PHONE AS \"Shipping Address Phone\", uc.BILLING_ADDRESS_ID AS \"Billing Address Id\", uc.BILLING_ADDRESS_NAME AS \"Billing Address Name\", uc.BILLING_ADDRESS_LINE_1 AS \"Billing Address Line 1\", uc.BILLING_ADDRESS_LINE_2 AS \"Billing Address Line 2\", uc.BILLING_ADDRESS_CITY AS \"Billing Address City\", uc.BILLING_ADDRESS_STATE AS \"Billing Address State\", uc.BILLING_ADDRESS_COUNTRY AS \"Billing Address Country\", uc.BILLING_ADDRESS_PINCODE AS \"Billing Address Pincode\", NULL AS \"Billing Address Latitude\", NULL AS \"Billing Address Longitude\", uc.BILLING_ADDRESS_PHONE AS \"Billing Address Phone\", NULL AS \"Combination Identifier\", NULL AS \"Combination Description\", CONCAT(sdj.so_code_so_number, sdj.item_seq) AS \"Sale Order Item Code*\", \'STD\' AS \"Shipping Method*\", sdj.sku_code AS \"Item SKU Code*\", NULL AS \"Channel Product Id\", NULL AS \"Item Name\", NULL AS \"Requires Customization\", NULL AS \"Gift Wrap\", uc.ACC_CODE AS \"Gift Message*\", sdj.cost_price AS \"Selling Price\", 0 AS \"Discount\", 0 AS \"Shipping Charges\", NULL AS \"Shipping Method Charges\", NULL AS \"COD Service Charges\", NULL AS \"Gift Wrap Charges\", NULL AS \"Voucher Code\", NULL AS \"Voucher Value\", NULL AS \"Store Credit\", NULL AS \"Packet Number\", NULL AS \"On Hold\", NULL AS \"Order Date as dd/mm/yyyy hh:MM:ss\", NULL AS \"Channel Order Processing Date as dd/MM/yyyy hh:mm:ss\", NULL AS \"Shipping Provider\", NULL AS \"Tracking Number\", sdj.socialistic AS \"Quantity\", NULL AS \"Quantity In Combo\", NULL AS \"Prepaid Amount\", NULL AS \"Customer Code\", NULL AS \"Currency Code\", NULL AS \"Customer GSTIN\", NULL AS \"Order Total Shipping Charges\", TO_CHAR(DATEADD(\'hour\', 16, DATEADD(\'day\', 2, CURRENT_DATE()::timestamp_ntz)),\'DD-MM-YYYY HH:MI AM\') AS \"Fulfillment Tat\", NULL AS \"Shipping Package Type Code\", NULL AS \"Transaction Id\", NULL AS \"Transaction Date as dd/MM/yyyy hh:mm:ss\", NULL AS \"Amount Paid\", NULL AS \"Payment Mode\", NULL AS \"Transaction Note\", sdj.facility AS \"Facility Code\", sdj.so_code_so_number AS \"Parent Sale Order Code\", NULL AS \"Item Tag\", NULL AS \"CHANNEL_ORDER_NUMBER\", NULL AS \"DiscountCode\", uc.ACC_CODE AS \"GiftMessage\", \'RPL\' AS \"Order_Type\", uc.SALEINVOICEPREFIX AS \"SaleInvoicePrefix\", NULL AS \"SnitchOnline\", uc.STORE_CODE AS \"STORE-CODE*\" FROM store_details_join_seq sdj LEFT JOIN STORE_DETAILS_UC uc ON sdj.branch_code = uc.store_code ), SO_FILTER AS ( SELECT \"Sales Order Code*\", SUM(\"Quantity\") FROM FINAL_OUTPUT GROUP BY 1 HAVING SUM(\"Quantity\") >= 15 ) SELECT * FROM FINAL_OUTPUT WHERE \"Sales Order Code*\" IN (SELECT \"Sales Order Code*\" FROM SO_FILTER) ORDER BY \"Sales Order Code*\", \"Facility Code\";",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            